#include <stdio.h>

int main(void) {
    int n, max = 0, x;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &x);
        if (x > max) {
            max = x;
        }
    }
    printf("%.1f\n", max);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, count = 0, x;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &x);
        if (x >= 100) {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}
